\section{Statistics over random topic models}\label{app:topic-stats}

This appendix collects the averages over the topic prior used in the main text.
Let $\mathbf{p},\mathbf{p}'\sim\mathrm{Dir}_K(\mathbf{1})$ be independent, i.e. uniform on the simplex $\Delta^{K-1}$, and let $\psi\,{=}\,\Gamma'/\Gamma$ denote the digamma function.
Each entry is marginally $p_a\sim\mathrm{Beta}(1,K{-}1)$, with moments
\begin{align}\label{eq:dirichlet-moments}
  \overline{p_a^{\,r}} = \frac{\Gamma(K)\,\Gamma(r{+}1)}{\Gamma(K{+}r)},
  \qquad
  \overline{\log p_a} = \psi(1) - \psi(K),
  \qquad
  \overline{p_a\log p_a} = \frac{1}{K}\left[\psi(2) - \psi(K{+}1)\right],
\end{align}
where the last two follow by differentiating the first with respect to $r$ at $r\,{=}\,0$ and $r\,{=}\,1$.

\paragraph{Entropy of a topic.}
By symmetry of the entries,
\begin{align}\label{eq:dirichlet-entropy}
  \overline{H(\mathbf{p})} = -K\,\overline{p_a\log p_a} = \psi(K{+}1) - \psi(2)
  = \log K - 1 + \gamma_{\mathrm{E}} + \frac{1}{2K} + O\!\left(K^{-2}\right),
\end{align}
using $\psi(2)\,{=}\,1-\gamma_{\mathrm{E}}$ and $\psi(K{+}1)\,{=}\,\log K + 1/(2K) + O(K^{-2})$.
A random topic thus has entropy $1-\gamma_{\mathrm{E}}-1/(2K)\approx0.42$ nats below the uniform value $\log K$, at leading orders: this gap is the height of the descent of every profile in~\autoref{fig:id-vs-ood-profiles}.

\paragraph{Divergence between two topics.}
Expanding the divergence and using the independence of $\mathbf{p}$ and $\mathbf{p}'$,
\begin{align}\label{eq:dirichlet-kl}
  \overline{\KL(\mathbf{p}\Vert\mathbf{p}')}
  = K\,\overline{p_a\log p_a} - K\,\overline{p_a}\;\overline{\log p'_a}
  = \left[\psi(2)-\psi(K{+}1)\right] - \left[\psi(1)-\psi(K)\right] = 1 - \frac{1}{K},
\end{align}
by the recurrence $\psi(x{+}1)\,{=}\,\psi(x)+1/x$.
Two random topics are thus separated by an order-one divergence for every vocabulary size, which sets the rate of topic resolution in~\autoref{app:specialised}.

\paragraph{Bhattacharyya coefficient.}
The non-asymptotic resolution bound of~\autoref{app:specialised} involves $\rho(\mathbf{p},\mathbf{p}')\,{:=}\,\sum_a\sqrt{p_a p'_a}$, whose average follows from~\autoref{eq:dirichlet-moments} at $r\,{=}\,1/2$,
\begin{align}\label{eq:dirichlet-bhattacharyya}
  \overline{\rho(\mathbf{p},\mathbf{p}')} = K\left(\overline{\sqrt{p_a}}\right)^2
  = \frac{\pi K}{4}\left[\frac{\Gamma(K)}{\Gamma(K{+}\tfrac12)}\right]^2
  = \frac{\pi}{4}\left(1 + \frac{1}{4K} + O\!\left(K^{-2}\right)\right).
\end{align}

\section{The specialised predictor}\label{app:specialised}

This appendix proves the statements of~\autoref{ssec:specialised}: the optimality of $\mathbf{q}_t$, the loss decomposition~\autoref{eq:specialised-loss}, and the resolution of the topic on the context scale $\log D$.
Throughout, the topic matrix $P$ is fixed, with distinct columns, and all expectations are over documents at fixed $P$.

\paragraph{Optimality.}
Conditional on the context, $X_{t+1}$ is distributed as $\mathbf{q}_t(X_{\leq t})$: by construction $q_t(a\mid X_{\leq t}) = \sum_z \mathbb{P}(Z\,{=}\,z\mid X_{\leq t})\,\mathbb{P}(X_{t+1}\,{=}\,a\mid Z\,{=}\,z)$, using that $X_{t+1}$ is independent of the context given $Z$.
For any predictor $\mathbf{f}$, therefore,
\begin{align}\label{eq:specialised-optimality}
  \mathbb{E}\left[-\log f_t(X_{t+1}\mid X_{\leq t}) \,\middle|\, X_{\leq t}\right]
  = H(\mathbf{q}_t) + \KL(\mathbf{q}_t\Vert\mathbf{f}_t) \geq H(\mathbf{q}_t),
\end{align}
with equality if and only if $\mathbf{f}_t\,{=}\,\mathbf{q}_t$.
Averaging over contexts, $\mathcal{L}_t[\mathbf{f}]\geq\mathcal{L}_t[\mathbf{q}]$.

\paragraph{Loss decomposition.}
Conditioning instead on the topic and the context, $X_{t+1}\sim\mathbf{p}_Z$, and the same identity gives $\mathbb{E}[-\log q_t(X_{t+1}\mid X_{\leq t})\mid Z, X_{\leq t}] = H(\mathbf{p}_Z) + \KL(\mathbf{p}_Z\Vert\mathbf{q}_t)$; averaging over the topic, uniform on $\lbrace 1,\dots,D\rbrace$, and over the context yields~\autoref{eq:specialised-loss}.
The floor is the loss of the oracle $\mathbf{f}_t\,{=}\,\mathbf{p}_Z$, which is not a function of the context and hence not a predictor in the sense of~\autoref{eq:ntp-loss}; by the optimality of $\mathbf{q}_t$, every predictor pays at least the excess $\mathbb{E}[\KL(\mathbf{p}_Z\Vert\mathbf{q}_t)]$ above it.

\paragraph{Excess loss and wrong-topic mass.}
Write the posterior in terms of the likelihood ratios of the wrong topics against the true one,
\begin{align}\label{eq:likelihood-ratio}
  R^{(t)}_{y} := \frac{\gamma_t(y)}{\gamma_t(Z)} = \prod_{s=1}^t \frac{p_y(X_s)}{p_Z(X_s)},
  \qquad
  \gamma_t(Z) = \Big(1 + \sum_{y\neq Z} R^{(t)}_y\Big)^{-1}.
\end{align}
Isolating the true topic in~\autoref{eq:specialised}, $\mathbf{q}_t = \gamma_t(Z)\,\mathbf{p}_Z + \sum_{y\neq Z}\gamma_t(y)\,\mathbf{p}_y \geq \gamma_t(Z)\,\mathbf{p}_Z$ entrywise, hence
\begin{align}\label{eq:excess-bound}
  \KL(\mathbf{p}_Z\Vert\mathbf{q}_t) \leq \sum_{a=1}^K p_Z(a)\log\frac{p_Z(a)}{\gamma_t(Z)\,p_Z(a)} = -\log\gamma_t(Z) = \log\Big(1 + \sum_{y\neq Z} R^{(t)}_y\Big).
\end{align}
Conditional on $Z$, the tokens are i.i.d. from $\mathbf{p}_Z$, so by the strong law of large numbers
\begin{align}\label{eq:lln-rate}
  \frac{1}{t}\log R^{(t)}_y = \frac{1}{t}\sum_{s=1}^t \log\frac{p_y(X_s)}{p_Z(X_s)} \xrightarrow[t\to\infty]{\mathrm{a.s.}} -\KL(\mathbf{p}_Z\Vert\mathbf{p}_y) < 0,
\end{align}
i.e. each wrong topic is suppressed exponentially in $t$, at a rate equal to its divergence from the true topic.
This is the mechanism described in the main text; it is asymptotic in $t$ at fixed $P$.

\paragraph{Resolution on the scale $\log D$.}
A bound valid at every $t$ follows from a fractional moment of the likelihood ratios.
Using $\log(1+\sum_y R_y)\leq\sum_y\log(1+R_y)\leq\sum_y\sqrt{R_y}$ in~\autoref{eq:excess-bound}, then the independence of the tokens given $Z$,
