\section{BACKGROUND AND RELATED WORK}
\label{sec:background}

\paragraph{Simulation-based inference.}
For conditionally independent observations $\y_n$, simulation-based inference targets $\postobs \propto p(\thetab)\, \prod_{n=1}^{N} p(\y_n \given \thetab)$ when the likelihood is unavailable.
Classical approximate Bayesian computation compares simulated and observed data directly, but becomes less effective as dimension increases \citep{sisson2018handbook}.
Neural posterior estimation (NPE) fits $q_{\psib}(\thetab\given\y)$ to simulated pairs and draws approximate posterior samples without running MCMC for each dataset.
Neural likelihood estimation (NLE), instead, fits a conditional density to prior-predictive pairs and uses it within MCMC \citep[for an overview, see][]{cranmer2020frontier}.
A per-observation estimator can be reused across dataset sizes, making single-trial likelihoods useful for models with exchangeable trials \citep{boelts2022flexible}, and spline coupling flows are the standard tractable-density baseline~\citep{durkan2019neural}.

\paragraph{Flow matching and diffusion-based inference.}
Flow matching learns a velocity field $\v(\z_t, t)$ that transports a Gaussian distribution to the target along a prescribed interpolation \citep{lipman2023flow, liu2022flow}.
It has been applied to both NPE and NLE, alongside score-based generative models \citep[for a review, see][]{arruda2025diffusion}.
Sampling requires ODE integration, and density evaluation additionally integrates the velocity divergence through the continuous change-of-variables formula \citep{chen2018neural}, so repeated integration can dominate the cost of NLE.

\paragraph{Few-step generative models.}
Consistency models learn transitions from intermediate noisy states toward data, enabling generation in one or a few steps \citep{song2023consistency}.
They also support fast posterior sampling in SBI \citep{schmitt2024consistency, arruda2025diffusion}, although the standard formulation does not provide a tractable posterior density.
Flow maps learn finite-time ODE transitions between arbitrary time pairs, and mean flows parameterize these maps through average velocities and can be trained without distillation \citep{geng2025mean, geng2026improved}.
\citet{rehman2026falcon} combined mean flows with a cycle loss that encourages invertibility to obtain few-step densities for Boltzmann generators.

\paragraph{MCMC with learned and multi-fidelity likelihoods.}
The no-U-turn sampler \citep[NUTS;][]{hoffman2014no-u-turn, betancourt2017conceptual} uses density and gradient evaluations to construct proposals, and probabilistic programming frameworks allow learned likelihoods to enter these calculations as model components \citep{carpenter2017stan}.
Delayed acceptance MCMC uses a cheap approximation to screen proposals while leaving the fine target invariant \citep{christen2005markov}.
Moreover, its multilevel variant organizes several approximations \citep{lykkegaard2023multilevel}, and related approaches in SBI use simulators at different resolutions \citep{prescott2021multifidelity, tatsuoka2026bifidelity}.


\section{METHOD}
\label{sec:method}

\paragraph{A note on notation.}
We write $\z$ for the density target and $\x$ for the conditioning variables.
In \emph{posterior estimation}, the network learns $q_{\psib}(\thetab\given\y)$ with parameters $\z\equiv\thetab$ as the target and data $\x\equiv\y$ as the condition.
In \emph{likelihood estimation}, it learns $q_{\psib}(\y\given\thetab)$ with $\z\equiv\y$ and $\x\equiv\thetab$.
The same formulation applies to either direction by choosing the target and condition accordingly.

\subsection{Flow-Based Density Evaluation}
\label{sec:flow-densities}

\paragraph{Flow matching vs.~normalizing flows.} We consider flows that transport the target distribution $p(\z \given \x)$ to a spherical Gaussian base distribution.
Time runs from data to noise: $t=0$ is the clean target and $t=1$ is pure noise, along the flow matching interpolation $\z_t = (1-t)\,\z_0 + t\,\epsilonb$ with $\epsilonb \sim \normal(\0, \I)$.
Flow matching for SBI learns the marginal velocity $\v_{\psib}(\z_t, t, \x)$ by regressing the conditional velocity $\epsilonb - \z_0$. For sampling, it draws the initial condition $\z_1\sim\normal(\0, \I)$ and then integrates $\mathrm{d}\z_t = \v_{\psib}\diff t$ from $t{=}1$ to $t{=}0$ \citep{wildberger2023flow}.
The density follows from the continuous change of variables,
\begin{equation}
    \log q_{\psib}(\z_0 \given \x) = \log \normal(\z_1; \0, \I) + \int_0^1 \nabla\!\cdot \v_{\psib}(\z_t, t, \x) \diff t,
    \label{eq:cnf}
\end{equation}
which can be integrated with any ODE solver \citep{arruda2025diffusion}.
Normalizing flows instead learn an invertible map $f_{\psib}(\cdot\,; \x)$ from the target to the base distribution and evaluate
\begin{equation}
    \begin{split}
    \log q_{\psib}(\z \given \x) ={}& \log \normal\big(f_{\psib}(\z; \x); \0, \I\big) \\
    &+ \log \big|\det \nabla_{\z} f_{\psib}(\z; \x)\big|
    \end{split}
    \label{eq:nf}
\end{equation}
in a single pass \citep{papamakarios2021normalizing}.
To keep the determinant tractable, $f_{\psib}$ is composed of invertible layers with triangular Jacobians \citep{dinh2017density, durkan2019neural}, which avoids the integral in \eqref{eq:cnf} but restricts the neural network architecture~(\autoref{fig:overview}).

\paragraph{Average velocity and the flow map.}
Extending \citet{geng2025mean} to conditional models, we train a network to predict the \emph{average velocity}
\begin{equation}
    \u_{\psib}(\z, s, t, \x) \approx \frac{1}{t-s} \int_s^t \v(\z_\tau, \tau, \x)\diff\tau ,
    \label{eq:average-velocity}
\end{equation}
the mean of the instantaneous field along the ODE trajectory started at $\z_s = \z$ conditioned on $\x$.
Since $\x$ is constant along the trajectory, the conditional velocity defines one ODE per condition.
One network evaluation then applies the finite-time \emph{flow map}
\begin{equation}
    \flowmap(\z; s, t, \x) = \z + (t - s)\,\u_{\psib}(\z, s, t, \x),
    \label{eq:flow-map}
\end{equation}
with the boundary case $\u_{\psib}(\z, t, t, \x)$ corresponding to the instantaneous velocity $\v$.

\paragraph{Training with a self-consistent tangent and a cycle loss.}
Differentiating $(t-s)\,\u = \int_s^t \v\diff\tau$ along the trajectory gives the MeanFlow identity \citep{geng2025mean},
\begin{equation}
    \v(\z_s, s, \x) = \u_{\psib}(\z_s, s, t, \x) - (t - s)\, \tfrac{\mathrm{d}}{\mathrm{d} s}\, \u_{\psib}(\z_s, s, t, \x),
    \label{eq:meanflow-identity}
\end{equation}
where $\nicefrac{\mathrm{d}}{\mathrm{d} s} = \v \cdot \nabla_{\z} + \partial_s$ is the total derivative along $(\dot\z_s, \dot s, \dot t) = (\v, 1, 0)$ at fixed $\x$.
Following \citet{geng2026improved}, we use the right-hand side as a prediction of the instantaneous velocity,
\begin{equation}
    \mathbf{V}_{\psib} = \u_{\psib}(\z_s, s, t, \x) - (t - s)\, \operatorname{sg}\!\big[\tfrac{\mathrm{d}}{\mathrm{d} s}\u_{\psib}(\z_s, s, t, \x)\big],
    \label{eq:compound-velocity}
\end{equation}
where $\operatorname{sg}[\cdot]$ denotes the stop-gradient and the total derivative is computed by one Jacobian-vector product with tangent $(\operatorname{sg}[\hat{\v}_{\psib}], 1, 0)$.
Since the marginal velocity $\v$ is unknown, the tangent $\hat{\v}_{\psib}(\z_s, s, \x)$ is predicted by an auxiliary velocity head, which shares all but the last two layers with $\u_{\psib}$.
With $\z_s = (1-s)\,\z_0 + s\,\epsilonb$, both outputs regress onto the conditional velocity,
\begin{equation}
    \loss_{\mathrm{MF}}(\psib) = \E\Big[ w\,\big\|\mathbf{V}_{\psib} - (\epsilonb - \z_0)\big\|^2 + \tfrac{1}{d}\big\|\hat{\v}_{\psib} - (\epsilonb - \z_0)\big\|^2 \Big],
    \label{eq:mf-loss}
\end{equation}
with the adaptive weight $w = \operatorname{sg}\big[(\|\mathbf{V}_{\psib} - (\epsilonb - \z_0)\|^2 + c)^{-p}\big]$ of \citet{geng2025mean} and $d$ the dimension of $\z$ (all hyperparameters are defined in \autoref{app:training}).
The expectation is taken over simulations $(\z_0, \x)$, noise $\epsilonb \sim \normal(\0, \I)$, and independent times $s, t$ drawn from a power-law distribution.
Hence, times are sampled more often closer to the target, similar to \citet{wildberger2023flow}.
For some of the pairs we set $t{=}s$, where $\mathbf{V}_{\psib} = \u_{\psib}(\z_s, s, s, \x)$ and \eqref{eq:mf-loss} reduces to flow matching.
Besides stabilizing training, the velocity head allows us to use the trained mean flow as a flow matching model.
To encourage invertibility of the flow map, we add the cycle loss of \citet{rehman2026falcon}, which penalizes the discrepancy between a state and its image after mapping $s \to t$ and back,
\begin{equation}
    \loss_{\mathrm{cyc}}(\psib) = \E\Big[\tfrac{1}{d}\big\|\z_s - \flowmap\big(\flowmap(\z_s;\, s, t, \x);\, t, s, \x\big)\big\|^2\Big],
    \label{eq:cycle-loss}
\end{equation}
and minimize $\loss_{\mathrm{MF}} + \lambda\,\loss_{\mathrm{cyc}}$ with the cycle weight $\lambda > 0$.
We further replace some $\x$ in \eqref{eq:cycle-loss} by the condition of another simulation, to encourage $\flowmap$ to be invertible for every condition and to make the map robust to any MCMC proposal.


\paragraph{Exact densities from composed steps.}
We fix a schedule $0 = t_0 < t_1 < \dots < t_S = 1$ and let $G_i(\z) = \flowmap(\z;\, t_{i-1}, t_i, \x)$ be the step maps toward noise.
With $\z^{(0)} = \z$ and $\z^{(i)} = G_i(\z^{(i-1)})$, the change-of-variables expression is
\begin{equation}
\begin{aligned}
    \log q_{\psib}^{(S)}(\z \given \x)
    &= \log \normal\big(\z^{(S)}; \0, \I\big) \\
    &\quad + \sum_{i=1}^{S} \log \big|\det \nabla_{\z} G_i\big(\z^{(i-1)}\big)\big|,
\end{aligned}
\label{eq:composed-density}
\end{equation}
where each Jacobian can be computed via autodiff.
If the composed map $T = G_S \circ \dots \circ G_1$ is a diffeomorphism of $\R^d$, the chain rule gives $\det \nabla_{\z} T = \prod_{i} \det \nabla_{\z} G_i$, so \eqref{eq:composed-density} is the pullback of the base density through $T$.
We place the nodes by an EDM schedule \citep{karras2022elucidating},
$t_i = (\sigma_i - \sigma_{\min})/(1 - \sigma_{\min})$ with $\sigma_i = \big(\sigma_{\min}^{1/\rho} + \tfrac{i}{S}(1 - \sigma_{\min}^{1/\rho})\big)^{\rho}$,
which concentrates the steps near the data for $\rho > 1$ and has been shown to outperform other schedules for few-step density evaluation~\citep{rehman2026falcon}.

\paragraph{Conditioning.}
Although the mean flow only receives $\x$ as an additional input and regresses the same target $\epsilonb - \z_0$ as an unconditional model, we show that it learns the correct conditional flow map.
Similar to conditional diffusion models \citep{vincent2011connection, batzolis2021conditional, arruda2025diffusion}, the condition only restricts which targets $\z_0$ contribute to the regression.

\begin{proposition}[Conditional mean flows]
\label{prop:conditional}
Under the assumptions of Appendix~\ref{app:conditional}, every population minimizer of the unweighted loss $\loss_{\mathrm{MF}}$ satisfies $\u_{\psib}=\u^*$ for $p(\x)$-almost every $\x$, where $\u^*$ is the average velocity \eqref{eq:average-velocity} of $\v^*(\z,s,\x)=\E[\epsilonb-\z_0\given\z_s=\z,\x]$.
Hence, \eqref{eq:composed-density} equals $\log p(\z \given \x)$ for every schedule.
\end{proposition}
The proof is given in Appendix~\ref{app:conditional}.


\subsection{Sampling and Posterior Inference}
\label{sec:sampling}

For sampling, we draw $\z^{(S)} \sim \normal(\0, \I)$ and apply the flow map backward along the same schedule, $\z^{(i-1)} = \flowmap(\z^{(i)};\, t_i, t_{i-1}, \x)$ for $i = S, \dots, 1$, so that $S$ steps yield a sample $\z^{(0)}$.
In the posterior direction, these are parameter draws conditional on the observed data; in the likelihood direction, they are observation draws conditional on the parameters.
These samples follow the density in \eqref{eq:composed-density} only if the backward maps invert the forward maps $G_i$, which the cycle loss encourages.

In the likelihood direction, the joint log-posterior of $N$ i.i.d.\ observations is proportional to $\log p(\thetab) + \sum_{n=1}^N \log q_{\psib}^{(S)}(\y_n \given \thetab)$, which is differentiable in $\thetab$ for any fixed $S$ with nonsingular step Jacobians.
We expose it to \texttt{PyMC} as a distribution  \citep{salvatier2016probabilistic} and sample with \texttt{nutpie}'s NUTS on the \texttt{JAX} backend \citep{seyboldt2026preconditioning}.

Additionally, we can construct a two-level sampler as a trained mean flow provides a coarse likelihood $q_{\psib}^{S_c}$ with few steps and a fine likelihood $q_{\psib}^{\mathrm{f}}$ by integrating its velocity head with an accurate ODE solver \eqref{eq:cnf}.
This defines a coarse and a fine posterior,
\begin{equation}
    \begin{aligned}
    \pi_{\mathrm{c}}(\thetab) &\propto p(\thetab) \textstyle\prod_{n=1}^N q_{\psib}^{S_c}(\y_n \given \thetab), \\
    \pi_{\mathrm{f}}(\thetab) &\propto p(\thetab) \textstyle\prod_{n=1}^N q_{\psib}^{\mathrm{f}}(\y_n \given \thetab),
    \end{aligned}
    \label{eq:two-level}
\end{equation}
which we combine in two-level delayed acceptance MCMC \citep{christen2005markov, lykkegaard2023multilevel}.
From the current state $\thetab$, a subchain of $J$ random-walk Metropolis steps targeting $\pi_{\mathrm{c}}$ yields a proposal $\thetab'$, which is accepted with probability
\begin{equation}
    \alpha(\thetab, \thetab') = \min\left\{1,\, \frac{\pi_{\mathrm{f}}(\thetab')\, \pi_{\mathrm{c}}(\thetab)}{\pi_{\mathrm{f}}(\thetab)\, \pi_{\mathrm{c}}(\thetab')}\right\}.
    \label{eq:delayed-acceptance}
\end{equation}
Since the subchain is reversible with respect to $\pi_{\mathrm{c}}$, this correction makes $\pi_{\mathrm{f}}$ the invariant distribution \citep{lykkegaard2023multilevel}, while the fine likelihood is evaluated only once per subchain instead of at every proposal.

\subsection{Masked Transformers for Marginal Densities}
\label{sec:backbone}

Inspired by the Simformer \citep{gloeckler2024all-in-one}, we use masked attention to learn marginal densities $p(\z_{\mathcal O}\given\x)$ for subsets $\mathcal O$ of the target coordinates.
Our transformer tokenizes each coordinate of $\z$ and $\x$ and receives $(s,s-t)$ through adaptive layer normalization \citep{peebles2023scalable}.
The mask excludes omitted target tokens, so outputs depend on $\z$ only through $\z_{\mathcal O}$; the mean-flow and cycle losses are restricted to $\mathcal O$.

\begin{proposition}[Marginalization by masking]
\label{prop:marginal}
Under the assumptions of Appendix~\ref{app:marginal}, every population minimizer of the unweighted masked loss satisfies $\u_{\psib,\mathcal O}=\u^*_{\mathcal O}$ for every training mask $\mathcal O$ and $p(\x)$-almost every $\x$, where $\u^*_{\mathcal O}$ is the average velocity of $\v^*_{\mathcal O}(\z_{\mathcal O},s,\x)=\E[\epsilonb_{\mathcal O}-\z_{0,\mathcal O}\given\z_{s,\mathcal O}=\z_{\mathcal O},\x]$.
Hence, \eqref{eq:composed-density} in $|\mathcal O|$ dimensions equals $\log p(\z_{\mathcal O}\given\x)$ for every schedule.
\end{proposition}
The proof is given in Appendix~\ref{app:marginal}.
Choosing $\z=\thetab$ gives marginal posterior densities $p(\thetab_{\mathcal O}\given\y)$; choosing $\z=\y$ gives marginal likelihoods $p(\y_{\mathcal O}\given\thetab)$.
We evaluate the latter for missing observations in \autoref{sec:exp3}.

\section{EXPERIMENTS}
\label{sec:experiments}

We evaluate direct posterior approximation on two moons and likelihood approximation on the three further benchmarks, where the learned densities enter MCMC.
The benchmarks show the following:
\begin{itemize}
    \item \textbf{Two moons}: few steps give accurate samples, so sampling has only a minor speed-accuracy trade-off, and densities improve with more steps~(\autoref{sec:exp1}).
    \item \textbf{Cognitive model}: exchangeable likelihoods yield precision comparable to 200-step flow matching with about $200\times$ faster MCMC~(\autoref{sec:exp2}).
    \item \textbf{Epidemic renewal}: a masked transformer marginalizes missing observations and is more accurate than a normalizing flow~(\autoref{sec:exp3}).
    \item \textbf{g-and-k}: at a shared budget, more draws beat more steps, and delayed acceptance MCMC is as accurate as NUTS without gradients~(\autoref{sec:exp4}).
\end{itemize}
We compare samples with exact references using the classifier two-sample test \citep[C2ST;][]{lopez-paz2017revisiting}, and densities through the Hellinger distance (\autoref{app:metrics}).
Reference-free evaluations use normalized root mean squared error (NRMSE), effective sample size (ESS) and predictive checks, and the calibration for every trained estimator is assessed using tests
of accuracy with random points \citep[TARP;][]{lemos2023sampling-based} prior to any other evaluation (\autoref{tab:tarp}).
Tasks, architectures and generative models are described in \autoref{app:metrics} to~\ref{app:tasks}.

